    //Driver Code Starts
class Heap {
    constructor(compare)
    {
        this.data = [];
        this.compare = compare;
    }

    push(val)
    {
        this.data.push(val);
        this._heapifyUp();
    }

    pop()
    {
        if (this.data.length === 0)
            return null;
        if (this.data.length === 1)
            return this.data.pop();

        const top = this.data[0];
        this.data[0] = this.data.pop();
        this._heapifyDown();
        return top;
    }

    peek() { return this.data[0] || null; }

    size() { return this.data.length; }

    _heapifyUp()
    {
        let index = this.data.length - 1;
        while (index > 0) {
            let parentIndex = Math.floor((index - 1) / 2);
            if (this.compare(this.data[parentIndex],
                             this.data[index]))
                break;

            [this.data[parentIndex], this.data[index]] = [
                this.data[index], this.data[parentIndex]
            ];
            index = parentIndex;
        }
    }

    _heapifyDown()
    {
        let index = 0;
        const length = this.data.length;

        while (true) {
            let leftChildIdx = 2 * index + 1;
            let rightChildIdx = 2 * index + 2;
            let swapIdx = index;

            if (leftChildIdx < length
                && !this.compare(this.data[swapIdx],
                                 this.data[leftChildIdx])) {
                swapIdx = leftChildIdx;
            }
            if (rightChildIdx < length
                && !this.compare(
                    this.data[swapIdx],
                    this.data[rightChildIdx])) {
                swapIdx = rightChildIdx;
            }
            if (swapIdx === index)
                break;

            [this.data[index], this.data[swapIdx]] =
                [ this.data[swapIdx], this.data[index] ];
            index = swapIdx;
        }
    }
}

